Local Ltac midV Rq eb ed cn :=
  constr:(fun j : nat => match j with 2%nat => sp | 10%nat => ov | 11%nat => v | 36%nat => ov + 8 | 37%nat => bv_unsigned (getr Rq (reg 18)) | 38%nat => eb | 39%nat => ed
     | 41%nat => osk | 42%nat => cn | 44%nat => r
     | 45%nat => bv_unsigned (getr R (reg 8)) | 46%nat => bv_unsigned (getr R (reg 9)) | 47%nat => bv_unsigned (getr R (reg 18)) | 48%nat => bv_unsigned (getr R (reg 19))
     | 49%nat => bv_unsigned (getr R (reg 20))
     | 55%nat => bv_unsigned (getr Rq (reg 10)) | 56%nat => bv_unsigned (getr Rq (reg 11)) | 57%nat => bv_unsigned (getr Rq (reg 12)) | 58%nat => bv_unsigned (getr Rq (reg 20)) | _ => 0 end).
Local Ltac feedP P := L5SAR.feed P ltac:(first [assumption | unfold PNAENU6P.aligned; assumption | apply wid | apply wrng | L5SAR.greg | L5SAR.gmem | lia]).

