Lemma vis Mq mdq LKq Awq crq kq lo hi : CINV Mq mdq LKq Awq crq kq lo hi ->
  let MV := mrestrict (ahid Awq mdq) Mq in
  (L5.img_clear MV 1376256 1409024 /\ L5.u64_at RSEGS MV 1440376 SBL /\ L5.u32_at RSEGS MV 1440384 1
   /\ 140735332487232 <= sp <= 140737488355328 /\ 0 <= sp < 2 ^ 64 /\ PNAENU6P.aligned sp 16 /\ L5.writable RSEGS MV (sp - 64) 64)
  /\ (4096 <= ov <= 140737488355272 /\ PNAENU6P.aligned ov 8 /\ (2147446784 + 17592186048512 <= ov \/ ov + 56 <= 2147446784) /\ L5KA.zeros_at MV (ov / 8 + SBL) 7
      /\ L5.writable RSEGS MV ov 56 /\ (sp - 64 + 64 <= ov \/ ov + 56 <= sp - 64)
      /\ L5KA.zeros_at MV ((ov + 8) / 8 + SBL) 1 /\ L5KA.zeros_at MV ((ov + 24) / 8 + SBL) 1 /\ L5KA.zeros_at MV ((ov + 32) / 8 + SBL) 1
      /\ L5.u64_at RSEGS MV (ov + 8) osk /\ 4096 <= osk <= 140737488355304 /\ PNAENU6P.aligned osk 8 /\ 0 <= ov < 2 ^ 64 /\ 0 <= osk < 2 ^ 64)
  /\ (4104 <= ov + 8 <= 140737488355280 /\ PNAENU6P.aligned (ov + 8) 8 /\ (2147446784 + 17592186048512 <= ov + 8 \/ ov + 8 + 8 <= 2147446784)
      /\ (ov + 8 + 8 <= sp - 64 \/ sp - 64 + 64 <= ov + 8) /\ 0 <= ov + 8 < 2 ^ 64)
  /\ (L5.u64_at RSEGS MV (sp - 8) r /\ L5.u64_at RSEGS MV (sp - 16) (bv_unsigned (getr R (reg 8))) /\ L5.u64_at RSEGS MV (sp - 24) (bv_unsigned (getr R (reg 9)))
      /\ L5.u64_at RSEGS MV (sp - 32) (bv_unsigned (getr R (reg 18))) /\ L5.u64_at RSEGS MV (sp - 40) (bv_unsigned (getr R (reg 19))) /\ L5.u64_at RSEGS MV (sp - 48) (bv_unsigned (getr R (reg 20))))
  /\ (L5.u64_at RSEGS MV (ov + 24) (en_b en) /\ L5.u64_at RSEGS MV (ov + 32) (en_b en + 24 * en_n en) /\ 0 <= en_b en <= 2 ^ 47 /\ 0 <= en_depth en <= en_n en).
